package com.yihe.framework.ehr;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.*;
import org.springframework.http.*;
import org.springframework.web.client.RestTemplate;
import org.springframework.http.client.SimpleClientHttpRequestFactory;
import com.fasterxml.jackson.databind.*;
import javax.annotation.PreDestroy;
import java.util.*;
import java.security.MessageDigest;
import java.util.concurrent.*;
import static com.yihe.framework.ehr.EhrAccess.*;
import static com.yihe.framework.ehr.EhrService.*;

/** Adapter/receipt layer only. No OCR engine or invented medical inference. */
@Service
public class EhrOcrService {
    final EhrRepository db;final EhrService ehr;final OcrResultContract contract;
    @Value("${ehr.data-mode:real}") private String runtimeMode;
    @Value("${ehr.ocr.callback-token:${EHR_OCR_CALLBACK_TOKEN:}}") String callbackToken;
    public EhrOcrService(EhrRepository db,EhrService ehr){this.db=db;this.ehr=ehr;this.contract=new OcrResultContract(db);}
    public void authorize(String header){require(!callbackToken.isEmpty(),503,"OCR接入密钥尚未配置");require(header!=null&&header.startsWith("Bearer ")&&MessageDigest.isEqual(bytes(callbackToken),bytes(header.substring(7))),401,"OCR接口鉴权失败");}
    Map<String,Object> job(String id,boolean lock){Map<String,Object> j=db.one("SELECT * FROM a_extraction_jobs WHERE job_id=? AND data_mode=?"+(lock?" FOR UPDATE":""),id,runtimeMode);require(j!=null,404,"识别任务不存在");return j;}
    EhrActor actor(Map<String,Object> j){String scope=str(j.get("scope_code"));require(scope.startsWith("org:"),422,"组织范围不合法");return new EhrActor("ocr-integration",scope.substring(4),str(j.get("data_mode")),false,false);}
    public boolean hasFile(String id,String file){Map<String,Object> j=job(id,false);return db.count("SELECT COUNT(*) FROM a_report_revision_sources WHERE report_id=? AND revision=? AND source_file_id=?",j.get("report_id"),j.get("revision"),file)==1;}
    public Map<String,Object> input(String jobId){
        Map<String,Object> j=job(jobId,false);EhrActor a=actor(j);
        Map<String,Object> r=ehr.rawReport(a,str(j.get("report_id")),num(j.get("revision")),false);
        List<Map<String,Object>> sources=contract.sourceFiles(j);
        @SuppressWarnings("unchecked") List<Map<String,Object>> files=(List<Map<String,Object>>)ehr.report(a,str(j.get("report_id")),num(j.get("revision")),false).get("files");
        for(Map<String,Object> file:files)for(Map<String,Object> source:sources)if(Objects.equals(file.get("id"),source.get("source_file_id")))file.put("sha256",source.get("sha256"));
        // Frozen contract context comes from A's persisted task, never from file names or worker guesses.
        return map("jobId",jobId,"job_id",jobId,"contractVersion","2.0.0","contract_version","2.0.0",
            "reportId",j.get("report_id"),"report_id",j.get("report_id"),"revision",j.get("revision"),
            "scope_code",j.get("scope_code"),"data_mode",j.get("data_mode"),
            "record_id",r.get("record_id"),"report_kind",r.get("report_kind"),"dictionary_version","2.0.0","prior_revision",r.get("prior_revision"),
            "files",files,"source_files",sources,
            "callbackPath","/ehr/integration/jobs/"+jobId+"/result");
    }
    public void validateContext(Map<String,Object> j,Map<String,Object> body,boolean required){
        for(String key:new String[]{"scope_code","data_mode"}){
            require(!required||body.get(key)!=null,422,"识别结果缺少任务上下文："+key);
            require(body.get(key)==null||Objects.equals(j.get(key),body.get(key)),422,"识别结果与A端任务上下文不一致："+key);
        }
        require(body.get("job_id")==null||Objects.equals(j.get("job_id"),body.get("job_id")),422,"识别结果任务关联冲突");
        if(body.get("report_kind")!=null){
            Map<String,Object> r=ehr.rawReport(actor(j),str(j.get("report_id")),num(j.get("revision")),false);
            String actual=str(body.get("report_kind"));
            // Only echo short enum-like tokens, never arbitrary worker text or report content.
            String display=actual.matches("[A-Za-z][A-Za-z0-9_-]{0,39}")?actual:"[不支持的类型值]";
            require(Objects.equals(r.get("report_kind"),body.get("report_kind"))||("individual".equals(r.get("report_kind"))&&"unknown".equals(actual)),422,"report_kind冲突：A端要求="+str(r.get("report_kind"))+"，B端回传="+display);
        }
    }
    @Transactional public Object start(EhrActor a,String rid,int rev){require(!a.mobile,403,"个人端不能重跑识别");Map<String,Object> h=ehr.rawReport(a,rid,rev,true);Map<String,Object> series=db.one("SELECT current_revision FROM a_report_series WHERE report_id=? FOR UPDATE",rid);require(num(series.get("current_revision"))==rev&&db.count("SELECT COUNT(*) FROM a_review_records WHERE report_id=? AND revision=?",rid,rev)==0,409,"仅当前未审核版本可重新识别");ehr.cancelOcrTasks(rid,rev,"后台重新发起识别，旧任务停止");String job=id();db.insert("a_extraction_jobs",ehr.scoped(a,"job_id",job,"report_id",rid,"revision",rev,"request_key",id(),"pipeline_version","external-ocr-worker-v1","status","uploaded","created_at",now(),"updated_at",now()));ehr.enqueueOcr(a,job);ehr.audit(a,str(h.get("record_id")),rid,rev,"ocr_requested","已加入持久识别队列，等待工作服务领取");return map("jobId",job,"status","queued");}
    @SuppressWarnings("unchecked") List<Map<String,Object>> array(Map<String,Object> b,String key){Object x=b.get(key);require(x instanceof List,422,key+"应为数组");List<?> a=(List<?>)x;require(a.size()<=2000,422,key+"记录过多");for(Object r:a)require(r instanceof Map,422,key+"元素应为对象");return (List<Map<String,Object>>)x;}
    String uuid(Object x){String s=str(x);require(s.matches("[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"),422,"证据或项目ID须为UUID");return s;}
    List<String> evidenceIds(Object x,Set<String> known){require(x instanceof List&&!((List<?>)x).isEmpty(),422,"缺少证据引用");List<String> ids=new ArrayList<>();for(Object v:(List<?>)x){String id=uuid(v);require(known.contains(id),422,"证据不属于本版本");ids.add(id);}return ids;}
    void rawOnly(Map<String,Object> row,String... keys){for(String k:keys)require(row.get(k)==null,422,"当前未批准归一化或单位转换："+k);}
    void fields(List<Map<String,Object>> fields,Set<String> known,boolean item){Set<String> allowed=new HashSet<>();for(Map<String,Object> d:db.all("SELECT field_key FROM a_standard_field_dictionary WHERE dictionary_version='2.0.0'"))allowed.add(str(d.get("field_key")));if(item)allowed.retainAll(Arrays.asList("check_date","lab_date","item_name","item_result","item_unit","item_reference","item_abnormal","item_abbreviation"));for(Map<String,Object> f:fields){require(allowed.contains(text(f,"field_key")),422,"未知的标准字段键");ehr.raw(f,"value_raw",20000);ehr.raw(f,"original_field_name",1000);rawOnly(f,"value_normalized","normalization_rule_version");evidenceIds(f.get("evidence_ids"),known);f.put("review_status","needs_review");}}
    @Transactional public Object result(String jobId,Map<String,Object> body){Map<String,Object> j=job(jobId,false);ehr.rawReport(actor(j),str(j.get("report_id")),num(j.get("revision")),true);j=job(jobId,true);EhrActor a=actor(j);validateContext(j,body,false);contract.validate(j,body);String rid=str(j.get("report_id"));int rev=num(j.get("revision"));ObjectMapper canonical=new ObjectMapper().configure(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS,true);String raw;try{raw=canonical.writeValueAsString(body);}catch(Exception e){throw new EhrException(422,"回调JSON不合法");}require(raw.length()<=5000000,413,"识别结果过大");byte[] hash=digest(bytes(raw));Map<String,Object> receipt=db.one("SELECT payload_sha256 FROM a_ehr_ocr_receipts WHERE job_id=?",jobId);if(receipt!=null){require(Arrays.equals(hash,(byte[])receipt.get("payload_sha256")),409,"同一识别任务已接收其他内容");return ehr.report(a,rid,rev,false);}
        Map<String,Object> h=ehr.rawReport(a,rid,rev,true);Map<String,Object> series=db.one("SELECT current_revision FROM a_report_series WHERE report_id=? FOR UPDATE",rid);require(num(series.get("current_revision"))==rev&&db.count("SELECT COUNT(*) FROM a_review_records WHERE report_id=? AND revision=?",rid,rev)==0,409,"版本过期或已审核");require(Arrays.asList("uploaded","failed").contains(str(j.get("status"))),409,"任务已处理或候选结果已被人工修改，请重新发起识别");Map<String,Object> latest=db.one("SELECT job_id FROM a_extraction_jobs WHERE report_id=? AND revision=? ORDER BY created_at DESC,job_id DESC LIMIT 1 FOR UPDATE",rid,rev);require(latest!=null&&jobId.equals(latest.get("job_id")),409,"已有更新的识别任务，旧回调不能覆盖候选结果");require("2.0.0".equals(body.get("contract_version")),422,"需要EHR数据契约2.0.0");require(body.get("report_id")==null||rid.equals(body.get("report_id")),422,"报告关联冲突");require(body.get("revision")==null||num(body.get("revision"))==rev,422,"报告版本冲突");
        for(String n:new String[]{"health_advice","health_conclusions","health_items","occupational_profiles","report_evidence"})db.exec("DELETE FROM a_"+n+" WHERE report_id=? AND revision=?",rid,rev);
        Set<String> known=new HashSet<>();for(Map<String,Object> e:array(body,"evidence")){String eid=uuid(e.get("evidence_id")),source=uuid(e.get("source_file_id"));Map<String,Object> file=db.one("SELECT s.page_count FROM a_report_revision_sources r JOIN a_report_sources s ON s.source_file_id=r.source_file_id WHERE r.report_id=? AND r.revision=? AND r.source_file_id=?",rid,rev,source);require(file!=null,422,"证据引用了未关联原件");int page=ehr.evidencePage(e.get("page_number"));require(page<=num(file.get("page_count")),422,"证据页码超出原件");require(known.add(eid),422,"证据ID重复");String method=text(e,"extraction_method"),coords=text(e,"coordinate_system");require(Arrays.asList("native_text","ocr","pdf_object").contains(method),422,"提取方法不合法");require(Arrays.asList("pdf_points_unrotated","image_pixels_top_left","object_only").contains(coords),422,"证据坐标系不合法");Object bbox=e.get("bbox");if(!coords.equals("object_only")){require(bbox instanceof List&&((List<?>)bbox).size()==4,422,"bbox应含四个坐标");List<?> b=(List<?>)bbox;for(Object x:b)require(x instanceof Number&&Double.isFinite(((Number)x).doubleValue())&&((Number)x).doubleValue()>=0,422,"bbox坐标不合法");require(((Number)b.get(2)).doubleValue()>((Number)b.get(0)).doubleValue()&&((Number)b.get(3)).doubleValue()>((Number)b.get(1)).doubleValue(),422,"bbox方向不合法");}else require(bbox==null,422,"object_only不应伪造坐标");
            db.insert("a_report_evidence",map("report_id",rid,"revision",rev,"evidence_id",eid,"source_file_id",source,"page_number",page,"bbox",bbox==null?null:ehr.encode(bbox),"coordinate_system",coords,"page_rotation",e.getOrDefault("page_rotation",0),"render_dpi",e.get("render_dpi"),"original_label",ehr.raw(e,"original_label",2000),"raw_fragment",e.get("raw_fragment")==null?null:ehr.raw(e,"raw_fragment",20000),"extraction_method",method,"extractor_version",ehr.safe(e,"extractor_version",120),"ocr_confidence",e.get("ocr_confidence"),"review_status","needs_review"));}
        List<Map<String,Object>> fv=array(body,"field_values");fields(fv,known,false);db.exec("UPDATE a_health_reports SET institution_raw=?,exam_date_raw=?,exam_date_verified=NULL,report_date_raw=?,exam_type_raw=?,exam_number_raw=?,age_raw=?,field_values=?,review_status='needs_review' WHERE report_id=? AND revision=?",body.get("institution_raw")==null?null:ehr.raw(body,"institution_raw",2000),body.get("exam_date_raw")==null?null:ehr.raw(body,"exam_date_raw",2000),body.get("report_date_raw")==null?null:ehr.raw(body,"report_date_raw",2000),body.get("exam_type_raw")==null?null:ehr.raw(body,"exam_type_raw",2000),body.get("exam_number_raw")==null?null:ehr.raw(body,"exam_number_raw",2000),body.get("age_raw")==null?null:ehr.raw(body,"age_raw",2000),ehr.encode(fv),rid,rev);
        int ordinal=0;for(Map<String,Object> item:array(body,"items")){ordinal++;String primary=uuid(item.get("primary_evidence_id"));List<String> refs=evidenceIds(item.get("evidence_ids"),known);require(refs.contains(primary),422,"主证据未列入证据引用");rawOnly(item,"result_normalized","unit_normalized","unit_conversion","normalization_rule_version");String code=ehr.safe(item,"item_code",64);Map<String,Object> d=code.isEmpty()?null:db.one("SELECT * FROM a_medical_item_dictionary WHERE item_code=? AND dictionary_version='2.0.0' AND status<>'retired'",code);require(code.isEmpty()||d!=null,422,"检查项目字典编码不存在");List<Map<String,Object>> iv=array(item,"field_values");fields(iv,known,true);db.insert("a_health_items",map("report_id",rid,"revision",rev,"item_id",item.get("item_id")==null?id():uuid(item.get("item_id")),"ordinal",item.get("ordinal")==null?ordinal:OcrResultContract.positiveInteger(item.get("ordinal"),"items.ordinal"),"primary_evidence_id",primary,"evidence_ids",ehr.encode(refs),"original_field_name",ehr.raw(item,"original_field_name",1000),"item_code",d==null?null:code,"dictionary_version",d==null?null:"2.0.0","standard_field_name",d==null?null:d.get("standard_name"),"abbreviation_raw",item.get("abbreviation_raw")==null?null:ehr.raw(item,"abbreviation_raw",1000),"result_raw",item.get("result_raw")==null?null:ehr.raw(item,"result_raw",20000),"unit_raw",item.get("unit_raw")==null?null:ehr.raw(item,"unit_raw",1000),"reference_range_raw",item.get("reference_range_raw")==null?null:ehr.raw(item,"reference_range_raw",4000),"abnormal_flag_raw",item.get("abnormal_flag_raw")==null?null:ehr.raw(item,"abnormal_flag_raw",1000),"field_values",ehr.encode(iv),"mapping_status",d==null?"unmapped":d.get("status"),"review_status","needs_review"));}
        for(Map<String,Object> row:array(body,"conclusions")){String primary=uuid(row.get("primary_evidence_id"));List<String> refs=evidenceIds(row.get("evidence_ids"),known);require(refs.contains(primary)&&row.get("standard_category")==null,422,"结论证据不合法，或OCR擅自给出正式分类");db.insert("a_health_conclusions",map("report_id",rid,"revision",rev,"conclusion_id",row.get("conclusion_id")==null?id():uuid(row.get("conclusion_id")),"primary_evidence_id",primary,"evidence_ids",ehr.encode(refs),"original_field_name",ehr.raw(row,"original_field_name",1000),"original_text",row.get("original_text")==null?null:ehr.raw(row,"original_text",20000),"completeness",text(row,"completeness"),"review_status","needs_review"));}
        for(Map<String,Object> row:array(body,"advice")){String ev=uuid(row.get("source_evidence_id"));require(known.contains(ev),422,"建议证据不属于本版本");db.insert("a_health_advice",map("report_id",rid,"revision",rev,"advice_id",row.get("advice_id")==null?id():uuid(row.get("advice_id")),"source_kind","pdf","source_evidence_id",ev,"original_field_name",ehr.raw(row,"original_field_name",1000),"text_raw",ehr.raw(row,"text_raw",20000),"review_status","needs_review"));}
        Set<String> occupational=new HashSet<>(Arrays.asList("job_type","employer","protection_measures","hazard_factors","exposure_duration","total_work_years","workshop","occupational_history","occupation_disease_history","exposure_start","department","work_years_other","org_unit_combined"));Map<String,Object> p=ehr.profile(a,str(h.get("record_id")),false);for(Map<String,Object> f:fv)if(occupational.contains(text(f,"field_key")))db.insert("a_occupational_profiles",ehr.scoped(a,"profile_id",id(),"report_id",rid,"revision",rev,"employee_id",p.get("employee_id"),"evidence_id",((List<?>)f.get("evidence_ids")).get(0),"field_key",f.get("field_key"),"original_field_name",f.get("original_field_name"),"value_raw",f.get("value_raw"),"review_status","needs_review","created_at",now()));
        db.insert("a_ehr_ocr_receipts",map("job_id",jobId,"payload_sha256",hash,"response_json",raw,"received_at",now()));db.exec("UPDATE a_extraction_jobs SET status='extracted',updated_at=UTC_TIMESTAMP(6) WHERE job_id=?",jobId);ehr.audit(a,str(h.get("record_id")),rid,rev,"ocr_candidate_received","已接收外部OCR候选，未核定体检日期，未自动审核归档");automaticQuality(a,rid,rev,str(h.get("record_id")),fv,str(body.get("report_kind")));ehr.completeness(a,str(h.get("record_id")));return ehr.report(a,rid,rev,false);
    }
    void automaticQuality(EhrActor a,String rid,int rev,String record,List<Map<String,Object>> fields,String detectedKind){
        Set<String> names=new HashSet<>();for(Map<String,Object> f:fields)if("full_name".equals(f.get("field_key"))&&!text(f,"value_raw").isEmpty())names.add(text(f,"value_raw"));
        String expected=str(ehr.profile(a,record,false).get("employee_name"));String identity=names.isEmpty()?"unmatched":names.size()>1?"ambiguous":names.contains(expected)?"matched":"conflict";List<Object> issues=new ArrayList<>();
        if("unknown".equals(detectedKind))issues.add(map("code","REPORT_KIND_UNCERTAIN","message","OCR未确定报告类型；仅保存个人档案候选，医生须核对原件并确认属于本人个人报告，不能把机构汇总或多人报告归入个人档案"));
        if(!identity.equals("matched"))issues.add(map("code","IDENTITY_REVIEW_REQUIRED","message","报告姓名缺失、存在歧义或与所选职工不一致，需人工核查"));
        if(db.count("SELECT COUNT(*) FROM a_health_items WHERE report_id=? AND revision=?",rid,rev)==0)issues.add(map("code","NO_ITEMS","message","未提取到检查项目，请核对原件或人工补录"));
        issues.add(map("code","DOCTOR_REVIEW_REQUIRED","message","识别结果仅为候选，体检日期与医学结论须医生核对"));
        db.insert("a_report_quality_checks",ehr.scoped(a,"quality_check_id",id(),"report_id",rid,"revision",rev,"status","needs_review","identity_status",identity,"issues",ehr.encode(issues),"report_digest",digest(bytes(ehr.encode(ehr.snapshot(rid,rev)))),"rule_version","ocr-receipt-validation-v1","checked_by_ref",bytes("ocr-worker-receipt"),"checked_at",now()));
    }
}
